   184	// readLines reads all lines from the named file and returns them as a
   185	// string slice.
   186	//
   187	// If filename is empty, readPatternsFromFile returns an empty slice.
   188	// If filename is a dash (-), readPatternsFromFile will read the lines from the
   189	// standard input.
   190	func readLines(filename string) ([]string, error) {
   191		if filename == "" {
   192			return nil, nil
   193		}
   194	
   195		var (
   196			data []byte
   197			err  error
   198		)
   199	
   200		if filename == "-" {
   201			data, err = io.ReadAll(os.Stdin)
   202		} else {
   203			data, err = textfile.Read(filename)
   204		}
   205	
   206		if err != nil {
   207			return nil, err
   208		}
   209	
   210		var lines []string
   211	
   212		scanner := bufio.NewScanner(bytes.NewReader(data))
   213		for scanner.Scan() {
   214			lines = append(lines, scanner.Text())
   215		}
   216	
   217		if err := scanner.Err(); err != nil {
   218			return nil, err
   219		}
   220		return lines, nil
   221	}
