   229			if f, err = os.Open(filename); err != nil {
   230				return nil, err
   231			}
   232		}
   233	
   234		names, err = readFilenamesRaw(f)
   235		if err != nil {
   236			// ignore subsequent errors
   237			_ = f.Close()
   238			return nil, err
   239		}
   240	
