   249	func readFilenamesRaw(r io.Reader) (names []string, err error) {
   250		br := bufio.NewReader(r)
   251		for {
   252			name, err := br.ReadString(0)
   253			switch err {
   254			case nil:
   255			case io.EOF:
   256				if name == "" {
   257					return names, nil
   258				}
   259				return nil, errors.Fatal("--files-from-raw: trailing zero byte missing")
   260			default:
   261				return nil, err
   262			}
   263	
   264			name = name[:len(name)-1]
   265			if name == "" {
   266				// The empty filename is never valid. Handle this now to
   267				// prevent downstream code from erroneously backing up
   268				// filepath.Clean("") == ".".
   269				return nil, errors.Fatal("--files-from-raw: empty filename in listing")
   270			}
   271			names = append(names, name)
   272		}
   273	}
