   367	// collectTargets returns a list of target files/dirs from several sources.
   368	func collectTargets(opts BackupOptions, args []string) (targets []string, err error) {
   369		if opts.Stdin {
   370			return nil, nil
   371		}
   372	
   373		for _, file := range opts.FilesFrom {
   374			fromfile, err := readLines(file)
   375			if err != nil {
   376				return nil, err
   377			}
   378	
   379			// expand wildcards
   380			for _, line := range fromfile {
   381				line = strings.TrimSpace(line)
   382				if line == "" || line[0] == '#' { // '#' marks a comment.
   383					continue
   384				}
   385	
   386				var expanded []string
   387				expanded, err := filepath.Glob(line)
   388				if err != nil {
   389					return nil, fmt.Errorf("pattern: %s: %w", line, err)
   390				}
   391				if len(expanded) == 0 {
   392					Warnf("pattern %q does not match any files, skipping\n", line)
   393				}
   394				targets = append(targets, expanded...)
   395			}
   396		}
   397	
   398		for _, file := range opts.FilesFromVerbatim {
   399			fromfile, err := readLines(file)
   400			if err != nil {
   401				return nil, err
   402			}
   403			for _, line := range fromfile {
   404				if line == "" {
   405					continue
   406				}
   407				targets = append(targets, line)
   408			}
   409		}
   410	
   411		for _, file := range opts.FilesFromRaw {
   412			fromfile, err := readFilenamesFromFileRaw(file)
   413			if err != nil {
   414				return nil, err
   415			}
   416			targets = append(targets, fromfile...)
   417		}
   418	
   419		// Merge args into files-from so we can reuse the normal args checks
   420		// and have the ability to use both files-from and args at the same time.
   421		targets = append(targets, args...)
   422		if len(targets) == 0 && !opts.Stdin {
   423			return nil, errors.Fatal("nothing to backup, please specify target files/dirs")
   424		}
   425	
   426		targets, err = filterExisting(targets)
   427		if err != nil {
   428			return nil, err
   429		}
   430	
   431		return targets, nil
   432	}
