   388	    fn test_comment_ignores() {
   389	        let cases = &[
   390	            // Trivial cases.
   391	            ("# zizmor: ignore[foo]", "foo", true),
   392	            ("# zizmor: ignore[foo,bar]", "foo", true),
   393	            // Dashes are OK.
   394	            ("# zizmor: ignore[foo,bar,foo-bar]", "foo-bar", true),
   395	            // Spaces are OK.
   396	            ("# zizmor: ignore[foo, bar,   foo-bar]", "foo-bar", true),
   397	            // Extra commas and duplicates are nonsense but OK.
   398	            ("# zizmor: ignore[foo,foo,,foo,,,,foo,]", "foo", true),
   399	            // Valid ignore, but not a match.
   400	            ("# zizmor: ignore[foo,bar]", "baz", false),
   401	            // Invalid ignore: empty rule list.
   402	            ("# zizmor: ignore[]", "", false),
   403	            ("# zizmor: ignore[]", "foo", false),
   404	            // Invalid ignore: no commas.
   405	            ("# zizmor: ignore[foo bar]", "foo", false),
   406	            // Invalid ignore: missing opening and/or closing [].
   407	            ("# zizmor: ignore[foo", "foo", false),
   408	            ("# zizmor: ignore foo", "foo", false),
   409	            ("# zizmor: ignore foo]", "foo", false),
   410	            // Invalid ignore: space after # and : is mandatory and fixed.
   411	            ("# zizmor:ignore[foo]", "foo", false),
   412	            ("#zizmor: ignore[foo]", "foo", false),
   413	            ("#  zizmor: ignore[foo]", "foo", false),
   414	            ("#  zizmor:  ignore[foo]", "foo", false),
   415	        ];
   416	
   417	        for (comment, rule, ignores) in cases {
   418	            assert_eq!(
   419	                Comment(comment).ignores(rule),
   420	                *ignores,
   421	                "{comment} does not ignore {rule}"
   422	            )
   423	        }
   424	    }
