   362	    // Walks recursively a serde_json::Value tree, expanding it into a Vec<(String, String)>
   363	    // according to the inner value of each node
   364	    fn walk_path(tree: &serde_json::Value, current_path: String) -> Vec<(String, String)> {
   365	        match tree {
   366	            Value::Null => vec![],
   367	
   368	            // In the case of scalars, we just convert the value to a string
   369	            Value::Bool(inner) => vec![(current_path, inner.to_string())],
   370	            Value::Number(inner) => vec![(current_path, inner.to_string())],
   371	            Value::String(inner) => vec![(current_path, inner.to_string())],
   372	
   373	            // In the case of an array, we recursively create on expansion pair for each item
   374	            Value::Array(inner) => inner
   375	                .iter()
   376	                .flat_map(|value| Matrix::walk_path(value, current_path.clone()))
   377	                .collect(),
   378	
   379	            // In the case of an object, we recursively create on expansion pair for each
   380	            // value in the key/value set, using the key to form the expanded path using
   381	            // the dot notation
   382	            Value::Object(inner) => inner
   383	                .iter()
   384	                .flat_map(|(key, value)| {
   385	                    let mut new_path = current_path.clone();
   386	                    new_path.push('.');
   387	                    new_path.push_str(key);
   388	                    Matrix::walk_path(value, new_path)
   389	                })
   390	                .collect(),
   391	        }
   392	    }
